import glob
props = {}
for f in glob.glob('outputs/01e_PARTIAL_*.json'):
    with open(f) as fh:
        data = json.load(fh)
    if isinstance(data, list):
        for p in data:
            pid = p.get('property_id','')
            if pid in prop_ids:
                props[pid] = p
    elif isinstance(data, dict):
        items = data.get('items', data.get('properties', [data]))
        if isinstance(items, list):
            for p in items:
                pid = p.get('property_id','')
                if pid in prop_ids:
                    props[pid] = p
print(f'Found {len(props)} properties out of {len(prop_ids)} needed')
for pid, p in sorted(props.items()):
    cs = p.get('code_scope', {})
    print(f'  {pid}: code_scope={json.dumps(cs)[:200] if cs else \"none\"}')
    print(f'    graph_elements={json.dumps(p.get(\"graph_elements\", p.get(\"covered_nodes\", \"N/A\")))[:200]}')
" 2>&1

